defined( 'ABSPATH' ) || exit;

/**
 * Get an icon SVG, with optional attributes merged into the root <svg>.
 *
 * @param string $name  Icon name (see Hatch_Icons::svgs()).
 * @param array  $attrs HTML attributes: class, width, height, etc.
 * @return string Sanitized SVG markup (safe to echo).
 */
function hatch_icon( string $name, array $attrs = array() ): string {
	$svgs = Hatch_Icons::svgs();
	if ( ! isset( $svgs[ $name ] ) ) {
		// Unknown icon — return a tiny invisible placeholder so layout doesn't shift.
		return '<svg class="hx-icon" viewBox="0 0 24 24" aria-hidden="true"></svg>';
	}

	$default_attrs = array(
		'xmlns'        => 'http://www.w3.org/2000/svg',
		'viewBox'      => '0 0 24 24',
		'fill'         => 'none',
		'stroke'       => 'currentColor',
		'stroke-width' => '1.8',
		'stroke-linecap'  => 'round',
		'stroke-linejoin' => 'round',
		'aria-hidden'  => 'true',
		'class'        => 'hx-icon',
	);
	$attrs = array_merge( $default_attrs, $attrs );

	$attr_str = '';
	foreach ( $attrs as $k => $v ) {
		$attr_str .= ' ' . esc_attr( $k ) . '="' . esc_attr( $v ) . '"';
	}

	// Inner SVG is from our static table — safe markup (no user input).
	return '<svg' . $attr_str . '>' . $svgs[ $name ] . '</svg>';
}

